// Thin fetch wrapper around the FastAPI backend.
// Base URL comes from .env (REACT_APP_API_URL), falling back to localhost:8000.
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

const TOKEN_KEY = 'cloudapp_token';

export const getToken = () => localStorage.getItem(TOKEN_KEY);
export const setToken = (token) => localStorage.setItem(TOKEN_KEY, token);
export const clearToken = () => localStorage.removeItem(TOKEN_KEY);

// Core request helper. Adds the Bearer token automatically when present,
// and throws an Error whose message is the backend's `detail` field so
// callers can show it directly to the user.
async function request(path, { method = 'GET', body, auth = true } = {}) {
  const headers = { 'Content-Type': 'application/json' };

  if (auth) {
    const token = getToken();
    if (token) headers.Authorization = `Bearer ${token}`;
  }

  const res = await fetch(`${API_URL}${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  // 204 / empty body responses
  const text = await res.text();
  const data = text ? JSON.parse(text) : null;

  if (!res.ok) {
    const message = (data && (data.detail || data.message)) || `Request failed (${res.status})`;
    throw new Error(typeof message === 'string' ? message : JSON.stringify(message));
  }

  return data;
}

export const api = {
  // ---- Auth ----
  register: (payload) => request('/auth/register', { method: 'POST', body: payload, auth: false }),
  login: (payload) => request('/auth/login', { method: 'POST', body: payload, auth: false }),
  me: () => request('/auth/me'),

  // ---- Assignments ----
  listAssignments: () => request('/assignments'),
  createAssignment: (payload) => request('/assignments', { method: 'POST', body: payload }),

  // ---- Submissions ----
  submitAssignment: (assignmentId, code) =>
    request(`/assignments/${assignmentId}/submit`, { method: 'POST', body: { code } }),
  listSubmissions: () => request('/submissions'),
  rateSubmission: (submissionId, rating) =>
    request(`/submissions/${submissionId}/rate`, { method: 'PATCH', body: { rating } }),

  // ---- Leaderboard & Run ----
  getLeaderboard: () => request('/leaderboard'),
  runCode: (code, language) => request('/run', { method: 'POST', body: { code, language } }),
};

export default api;
